#!/usr/bin/env python3
"""
patch-155 — 24-hour delivery reminders.

Mirror of patch-154 (appointment reminders) for the deliveries feature.

What ships:
  - Migration: reminded_at column on tenant_deliveries + composite index.
  - Artisan command: deliveries:remind
      * Loops active tenants, computes 23-25h window in tenant TZ.
      * Finds non-cancelled rows with reminded_at IS NULL in window.
      * Calls TenantDeliveryNotificationService::sendReminder() for each.
      * Stamps reminded_at on every visited row (idempotence).
      * --dry-run + --tenant=ID flags for debugging.
  - Hourly scheduler entry in routes/console.php.
  - TenantDeliveryNotificationService extended with sendReminder() that
    uses *_reminder template keys + delivery_reminder_* toggle keys.
  - EmailService gains 2 new default templates:
      * delivery_pickup_reminder
      * delivery_dropoff_reminder
  - Settings panel: new "Delivery reminder" row (WIRED, defaults ON).
  - SettingsController validates + saves 2 new toggle keys.

Simpler than 154 — deliveries always have a precise scheduled_at,
so no drop-off-mode fallback is needed.

Standalone Python. Idempotent.
"""
import argparse, base64, pathlib, sys

